package com.dentalcrm.dashboard;
import com.dentalcrm.appointment.*; import com.dentalcrm.patient.PatientRepository; import com.dentalcrm.payment.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.OffsetDateTime; import static com.dentalcrm.dashboard.DashboardDtos.*;
@Service public class DashboardService {private final PatientRepository patients;private final AppointmentRepository appointments;private final PaymentRepository payments;public DashboardService(PatientRepository p,AppointmentRepository a,PaymentRepository pay){patients=p;appointments=a;payments=pay;}
 @Transactional(readOnly=true) public DashboardSummary summary(OffsetDateTime from,OffsetDateTime to){if(!to.isAfter(from))throw new IllegalArgumentException("to must be after from");var appts=appointments.findByStartTimeBetweenOrderByStartTime(from,to);var paid=payments.findByPaidAtBetween(from,to);BigDecimal cash=sum(paid,PaymentMethod.CASH),card=sum(paid,PaymentMethod.CARD),qr=sum(paid,PaymentMethod.QR);return new DashboardSummary(from,to,patients.count(),appts.size(),appts.stream().filter(a->a.getStatus()==AppointmentStatus.COMPLETED).count(),appts.stream().filter(a->a.getStatus()==AppointmentStatus.CANCELLED).count(),cash.add(card).add(qr),cash,card,qr);}
 private BigDecimal sum(java.util.List<Payment> p,PaymentMethod m){return p.stream().filter(x->x.getPaymentMethod()==m).map(Payment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}
}
